package br.com.sussmartcare.notification.infrastructure; import jakarta.persistence.*; import java.time.*; import java.util.*; @Entity @Table(name="pending_visit_notifications") public class PendingVisitNotification{@Id private UUID eventId;@Column(nullable=false)private UUID visitId;@Column(nullable=false)private String type;@Column(nullable=false,length=1200)private String message;@Column(nullable=false)private Instant createdAt;protected PendingVisitNotification(){}public PendingVisitNotification(UUID e,UUID v,String t,String m){eventId=e;visitId=v;type=t;message=m;createdAt=Instant.now();}public UUID getEventId(){return eventId;}public UUID getVisitId(){return visitId;}public String getType(){return type;}public String getMessage(){return message;}}